#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){ifstream f(argv[1],ios::binary);int W,H;f.read((char*)&W,4);f.read((char*)&H,4);int N=W*H; vector<unsigned char> m(N*3),v(N);f.read((char*)m.data(),N*3);f.read((char*)v.data(),N);int na,nz;f.read((char*)&na,4);vector<int>a(na);f.read((char*)a.data(),na*4);f.read((char*)&nz,4);vector<int>z(nz);f.read((char*)z.data(),nz*4);vector<char>goal(N*3);for(int q:z)goal[q]=1;vector<float>d(N*3,1e30);vector<int>p(N*3,-1);priority_queue<pair<float,int>,vector<pair<float,int>>,greater<pair<float,int>>>pq;for(int q:a)if(!m[q])d[q]=0,pq.push({0,q});int end=-1;int dx[]={1,-1,0,0,1,1,-1,-1};int dy[]={0,0,1,-1,1,-1,1,-1};while(!pq.empty()){auto[g,q]=pq.top();pq.pop();if(g>d[q]+1e-4)continue;if(goal[q]){end=q;break;}int l=q/N,k=q%N,y=k/W,x=k%W;for(int i=0;i<8;i++){int xx=x+dx[i],yy=y+dy[i];if(xx<0||xx>=W||yy<0||yy>=H)continue;int t=l*N+yy*W+xx;if(m[t])continue;if(i>=4&&(m[l*N+y*W+xx]||m[l*N+yy*W+x]))continue;float ng=g+(i<4?1:1.41421356)*(l==2?4.0:1);if(ng<d[t]){d[t]=ng;p[t]=q;pq.push({ng,t});}}if(!v[k])for(int ll=0;ll<3;ll++){int t=ll*N+k;if(ll==l||m[t])continue;float ng=g+30;if(ng<d[t]){d[t]=ng;p[t]=q;pq.push({ng,t});}}}ofstream o(argv[2]);if(end<0){o<<"[]";return 1;}vector<int>path;for(int q=end;q>=0;q=p[q])path.push_back(q);reverse(path.begin(),path.end());o<<"[";bool first=true;for(int q:path){if(!first)o<<",";first=false;o<<"["<<q%N%W<<","<<q%N/W<<","<<q/N<<"]";}o<<"]";}
